-- Migration 430: bg_shashtiamsha_deities — canonical D60 (Shashtiamsha) reference table
-- (R6 1b-vargas, M-17)
--
-- Context: M-17 (MARSYS_DEFECT_GAP_REGISTER_v2_0.md) — ga_vargas_writer.py's D60 deity/quality
-- attribution was fabricated: D60_QUALITIES = ["Malefic","Neutral","Benefic"]*20 (a naive 3-cycle
-- repeating every 1.5 degrees within EACH sign, independent of amsa number or sign parity) and
-- D60_DEITIES ignored sign-parity entirely (_get_d60_deity only used degree-in-sign, never sign_idx,
-- despite classical Shashtiamsha requiring an odd/even-sign amsa-order reversal — see PyJHora's own
-- jhora.utils.get_amsa_ruler_from_planet_longitude, which reverses the 60-amsa index for even signs).
-- D60 carries the HIGHEST vimshopaka weight in serving (priors_config D60=0.95), so this fabricated
-- quality axis was the single highest-leverage falsification surface in the varga estate.
--
-- This migration replaces the fabricated per-degree cycling with the REAL classical kroora
-- (malefic)/soumya (benefic) Shashtiamsha split, cross-derived 1:1 from PyJHora's own reference
-- arrays (jhora.const.shashti_amsa_rulers_kroora / shashti_amsa_rulers_soumya, 0-based indices
-- converted to 1-based amsa_number here) — 23 kroora + 37 soumya = 60, verified disjoint and total.
-- This is real delegated classical data, not invented.
--
-- deity_name is intentionally NULL for all 60 rows: PyJHora ships only the kroora/soumya quality
-- split for Shashtiamsha (it does not materialize named deities either — evidently because named
-- attribution requires a primary BPHS Ch.7 verse-level citation this session could not verify against
-- a primary source). Per CLAUDE.md's canonical-or-floor rail ("canonical cited value OR floor NULL +
-- reason — NEVER a computable substitute"), a NULL + documented reason is correct here; a guessed
-- 60-name list (the prior D60_DEITIES array's failure mode) would be a B.10 fabrication regression,
-- not a fix. deity_name may be populated in a follow-up migration if/when a primary BPHS citation is
-- sourced — this table's shape already supports that (ADD is additive; no consumer depends on NULL).
--
-- ga_vargas_writer.py's D60 branch of _build_deity_rows now JOIN-reads this table by the correctly
-- sign-parity-reversed amsa_number (derived-by-JOIN at write time, never hand-copied — L1-authority
-- discipline, CLAUDE.md §N.5) instead of indexing the old fabricated Python lists.

BEGIN;

CREATE TABLE IF NOT EXISTS bg_shashtiamsha_deities (
    amsa_number         INTEGER     PRIMARY KEY
                        CHECK (amsa_number BETWEEN 1 AND 60),
    quality             TEXT        NOT NULL
                        CHECK (quality IN ('kroora', 'soumya')),
    deity_name          TEXT,
    classical_citation  TEXT        NOT NULL,
    rule_notes          TEXT
);

COMMENT ON TABLE bg_shashtiamsha_deities IS
  'M-17: canonical D60 (Shashtiamsha) amsa-quality reference — 60 amsas (0.5 deg each), '
  'kroora (malefic) / soumya (benefic) classification cross-derived from PyJHora '
  'jhora.const.shashti_amsa_rulers_kroora/soumya. deity_name floored NULL pending a primary '
  'BPHS Ch.7 verse-level citation (canonical-or-floor; never a guessed name). Consumed by '
  'ga_vargas_writer.py varga_deity_attribution rows for D60 via JOIN on the sign-parity-reversed '
  'amsa_number (PyJHora convention: amsa index reverses for even signs — see '
  'jhora.utils.get_amsa_ruler_from_planet_longitude).';

