ON CONFLICT (amsa_number) DO UPDATE SET
    quality             = EXCLUDED.quality,
    deity_name          = EXCLUDED.deity_name,
    classical_citation  = EXCLUDED.classical_citation,
    rule_notes          = EXCLUDED.rule_notes;

-- Invariant check: exactly 23 kroora + 37 soumya = 60 rows (matches PyJHora's own arrays).
DO $$
DECLARE
    kroora_count INTEGER;
    soumya_count INTEGER;
    total_count INTEGER;
BEGIN
    SELECT count(*) INTO kroora_count FROM bg_shashtiamsha_deities WHERE quality = 'kroora';
    SELECT count(*) INTO soumya_count FROM bg_shashtiamsha_deities WHERE quality = 'soumya';
    SELECT count(*) INTO total_count FROM bg_shashtiamsha_deities;
    IF kroora_count != 23 OR soumya_count != 37 OR total_count != 60 THEN
        RAISE EXCEPTION 'bg_shashtiamsha_deities invariant violated: kroora=%, soumya=%, total=% (expected 23/37/60)',
            kroora_count, soumya_count, total_count;
    END IF;
END $$;

COMMIT;
